from auto_config.generator.bts.bts import BTS
from auto_config.generator.enb.params_generator_factory import ParamsGeneratorFactory
from auto_config.generator.utils.logger import logger


class ENB(BTS):

    def get_params_generator_factory(self):
        return ParamsGeneratorFactory()

    def add_specific_mocs(self, dist_names, enb_ent_config, execution_config):
        self.add_ecpri_mocs(dist_names, enb_ent_config)
        self.add_vlan_mocs(dist_names, enb_ent_config, execution_config)

    def update_managed_object_occurrences(self, enb_ent_config, execution_config, pddb_topology, epc_config):
        occurrences = {
            'LNBTS': 1,
            'LNCEL': enb_ent_config['cells_count'],
            'LCELL': enb_ent_config['cells_count'],
            'ANRPRL': 1,
            'SCTP': 1,
            'LNMME': 1,
            'SMOD': enb_ent_config['smods_count'],
            'RMOD': enb_ent_config['radios_count'],
            'PMRNL': 1,
            'REDRT': 1,
            'PMCADM': 1,
            'SECADM': 1,
            'TRBLCADM': 1,
            'CABLINK': enb_ent_config['bbmods_count'] + enb_ent_config['radios_count'],
            'ANR': 1,
            'PMQAP': 1,
            'SIB': 1,
            'DRX': 1,
            'PMCCP': 1,
            'HWTOP': 1,
            'EQM': 1,
            'APEQM': 1,
            'CABINET': 1,
            'CMD': 1,
            'MNLENT': 1,
            'SYNC': 1,
            'TIME': 1,
            'FEATCADM': 1,
            'FMCADM': 1,
            'CELLMAPPING': 1,
            'CHANNELGROUP': 1,
            'CHANNEL': [len(cell['channels']) for cell in enb_ent_config['cells'].values()],
            'LBPUCCHRDPR': 1,
            'TEST': 1,
            'RFTHLD': 1,
            'BBMOD': enb_ent_config['bbmods_count'],
            'FEATLADM': 1,
            'FEATGADM': 1,
            'CAGENB': 1,
            'DNS': 1,
            'PMMNL': 1,
            'TRSNW': 1,
            'AMGR': 1,
            'LUAC': 1,
            'CERTH': 1,
            'CMP': 1,
            'NTP': 1,
            'TAC': 1,
            'LTAC': 1,
            'TNLSVC': 1,
            'TNL': 1,
            'ETHSVC': 1,
            'ETHIF': 2,
            'ETHLK': 1,
            'L2SWI': 1,
            'BRGPRT': 1,
            'DSCPTOQMAP': 1,
            'IBRGPRT': 1,
            'PCP2QMAP': 1,
            'IPAPP': 1,
            'IPSECC': 1,
            'IPNO': 1,
            'IPIF': 1,
            'IPRT': 1,
            'IPRTV6': 1,
            'QOS': 1,
            'DSCP2PCPMAP': 1,
            'DSCP2QMAP': 1,
            'MPLANENW': 1,
            'RTPOL': 1,
            'FIREWALL': 1,
            'PKTFLTR': 1,
        }

        if execution_config['release'] > 22.32202:
            occurrences['CMPECDSA'] = 1

        if execution_config['release'] > 20.7:
            occurrences['PMPLM'] = 1

        if 'HW' in pddb_topology:
            occurrences['HW'] = 0

        optional_managed_objects_funcs = (
            self.update_sran_managed_objects,
            self.update_antenna_managed_objects,
            self.update_sync_managed_objects,
            self.update_duplex_managed_objects,
            self.update_fsm4_managed_objects,
            self.update_fsm5_managed_objects,
            self.update_fsm6_managed_objects,
        )

        for func in optional_managed_objects_funcs:
            func(occurrences, enb_ent_config, execution_config, pddb_topology)

        for mo_name, occurrences in occurrences.items():
            pddb_topology[mo_name]['mo_min_occurs'] = occurrences

    def update_starting_index(self, enb_ent_config, pddb_params, pddb_topology):
        def set_starting_index(mo_name, starting_index_value):
            # nonlocal pddb_params, pddb_topology
            index_name = pddb_topology[mo_name]['index']
            pddb_params[mo_name][index_name]['range'] = starting_index_value

        set_starting_index('LNBTS', enb_ent_config['id'])
        set_starting_index('LNCEL', 1)
        set_starting_index('LCELL', 1)

        # Workaround for ANTL managed object
        # Every new parent doesn't cause starting indexing from constant index; in this case index is a cumulative sum
        # E.G. RMOD-1/ANTL-4 -> RMOD-2/ANTL-5 (instead of RMOD-2/ANTL-1)
        antl_start_indices_list = [
            1 + sum(pddb_topology['ANTL']['mo_min_occurs'][:i])
            for i in range(len(pddb_topology['ANTL']['mo_min_occurs']))
        ]

        set_starting_index('ANTL', antl_start_indices_list)

    @staticmethod
    def update_sran_managed_objects(occurrences, enb_ent_config, execution_config, pddb_topology):

        logger.info("Adding SRAN Managed Objects")

        if enb_ent_config['is_ipv4']:
            occurrences['IPADDRESSV4'] = 1

        if enb_ent_config['is_ipv6']:
            occurrences['IPADDRESSV6'] = 1

        if 'PMTNL' in pddb_topology:
            occurrences['PMTNL'] = 1
        elif 'PMTNLINT' in pddb_topology:
            occurrences['PMTNLINT'] = 1
        else:
            logger.info("Neither PMTNL nor PMTNLINT exists in PDDB")

        if execution_config['release'] > 22.2:
            occurrences['CUPLANEFHNW'] = 1

    @staticmethod
    def update_duplex_managed_objects(occurrences, enb_ent_config, execution_config, pddb_topology):
        if enb_ent_config['cells_count_fdd'] > 0:
            logger.info("Adding FDD Managed Objects")
            occurrences['LNBTS_FDD'] = 1
            occurrences['LNCEL_FDD'] = 1
            occurrences['MPUCCH_FDD'] = 1
            apucch_fdd_occurrences = [
                int(cell_ent.get('dl_mimo_mode') == 'Closed Loop MIMO (4x4)' or execution_config['is_fsm5'])
                for cell_ent in enb_ent_config['cells'].values() if cell_ent['is_fdd']
            ]
            occurrences['APUCCH_FDD'] = apucch_fdd_occurrences

        if enb_ent_config['cells_count_tdd'] > 0:
            logger.info("Adding TDD Managed Objects")
            occurrences['LNBTS_TDD'] = 1
            occurrences['LNCEL_TDD'] = 1
            occurrences['MPUCCH_TDD'] = 1
            apucch_tdd_occurrences = [
                int(cell_ent.get('dl_mimo_mode') == 'Closed Loop MIMO (4x4)' or execution_config['is_fsm5'])
                for cell_ent in enb_ent_config['cells'].values() if not cell_ent['is_fdd']
            ]
            occurrences['APUCCH_TDD'] = apucch_tdd_occurrences

    @staticmethod
    def update_fsm4_managed_objects(occurrences, enb_ent_config, execution_config, pddb_topology):
        if execution_config['is_fsm4'] and 'bbpoolalloc' in enb_ent_config:
            logger.info("Adding FSM4 Mandatory Objects...")
            occurrences['BBPOOLALLOC'] = 1

    @staticmethod
    def update_antenna_managed_objects(occurrences, enb_ent_config, execution_config, pddb_topology):
        logger.info("Adding Antenna Managed Objects...")

        radios = []
        for radio_id in sorted(enb_ent_config['radios'], key=int):
            radios.append(enb_ent_config['radios'][radio_id])
        antl_occurrences_list = [radio['antenna_count'] for radio in radios]
        rsl_occurrences_list = [radio['ret_count'] for radio in radios]

        occurrences.update({
            'ANTL': antl_occurrences_list,
            'RSL': rsl_occurrences_list
        })

    @staticmethod
    def update_sync_managed_objects(occurrences, enb_ent_config, execution_config, pddb_topology):
        logger.info("Adding SYNC Managed Objects...")

        occurrences['CLOCK'] = enb_ent_config['smods_count']
        if 'smods' in enb_ent_config and enb_ent_config['smods']['1'].get('prod_code_planned') == "476147A":
            occurrences['GNSSI'] = 1

        if enb_ent_config['has_top_sync']:
            if enb_ent_config['has_freq_sync']:
                occurrences['TOPF'] = 1
        else:
            occurrences['GNSSE'] = [1, 0]

        if enb_ent_config['sync'].startswith('top'):
            occurrences['TOP'] = 1

    @staticmethod
    def update_fsm5_managed_objects(occurrences, enb_ent_config, execution_config, pddb_topology):
        if execution_config['is_fsm5']:
            logger.info("Adding FSM5 Mandatory Objects...")
            occurrences.update({
                'BBADM': 1,
                'CAPCFG': 1,
                'BBPOOLALLOC': 1,
                'BBPOOL': enb_ent_config['bbpool_count'],
            })

    @staticmethod
    def update_fsm6_managed_objects(occurrences, enb_ent_config, execution_config, pddb_topology):
        if execution_config['is_fsm6']:
            logger.info("Adding FSM6 Mandatory Objects...")
            occurrences['BBCAP'] = 1

    @staticmethod
    def add_ecpri_mocs(dist_names, enb_ent_config):
        if enb_ent_config['is_ecpri']:
            enb_id = enb_ent_config['id']
            logger.info("Updating Managed Objects with CUS 2.0 objects...")
            dist_names.extend([
                f"MRBTS-{enb_id}/TNLSVC-1/TNL-2",
                f"MRBTS-{enb_id}/TNLSVC-1/TNL-2/ETHSVC-1",
                f"MRBTS-{enb_id}/TNLSVC-1/TNL-2/IPNO-1"]
            )
            for radio_num in sorted(enb_ent_config['radios'], key=int):
                dist_names.extend([
                    f"MRBTS-{enb_id}/TNLSVC-1/TNL-2/ETHSVC-1/ETHIF-{radio_num}",
                    f"MRBTS-{enb_id}/TNLSVC-1/TNL-2/ETHSVC-1/ETHIF-{radio_num}/VLANIF-1",
                    f"MRBTS-{enb_id}/TNLSVC-1/TNL-2/ETHSVC-1/ETHLK-{radio_num}",
                ])

            dist_names.extend([
                f"MRBTS-{enb_id}/MNL-1/MNLENT-1/SYNC-1/ECPRIMASTER-1",
                f"MRBTS-{enb_id}/MNL-1/MNLENT-1/SYNC-2",
                f"MRBTS-{enb_id}/MNL-1/MNLENT-1/SYNC-2/CLOCK-1",
                f"MRBTS-{enb_id}/MNL-1/MNLENT-1/SYNC-2/CLOCK-1/TOP-1",
                f"MRBTS-{enb_id}/MNL-1/MNLENT-1/SYNC-2/CLOCK-1/TOP-1/TOPP-1",
                f"MRBTS-{enb_id}/MNL-1/MNLENT-1/SYNC-2/TIME-1"
            ])

    @staticmethod
    def add_vlan_mocs(dist_names, enb_ent_config, execution_config):
        if execution_config['vlan_id']:
            logger.info("Updating Managed Objects with VLANIF")
            dist_names.append(f'MRBTS-{enb_ent_config["id"]}/TNLSVC-1/TNL-1/ETHSVC-1/ETHIF-1/VLANIF-1')
